#include <stdio.h>
#include <stdlib.h>

static char ibuf[1 << 16];
static int ipos = 0, ilen = 0;

static int gc(void) {
    if (ipos == ilen) {
        ilen = (int)fread(ibuf, 1, sizeof(ibuf), stdin);
        ipos = 0;
        if (ilen <= 0) return -1;
    }
    return (unsigned char)ibuf[ipos++];
}

static long long readInt(void) {
    int c = gc();
    while (c != -1 && (c < '0' || c > '9')) c = gc();
    long long x = 0;
    while (c >= '0' && c <= '9') {
        x = x * 10 + (c - '0');
        c = gc();
    }
    return x;
}

#define MAXN 100005

static long long fval[MAXN];
static int tval[MAXN];

typedef struct {
    long long key;
    int idx;
} HN;

static HN heapArr[MAXN];
static int hn;

static void hpush(long long key, int idx) {
    int i = ++hn;
    heapArr[i].key = key;
    heapArr[i].idx = idx;
    while (i > 1) {
        int p = i >> 1;
        if (heapArr[p].key <= heapArr[i].key) break;
        HN tmp = heapArr[p]; heapArr[p] = heapArr[i]; heapArr[i] = tmp;
        i = p;
    }
}

static void hpop(HN *out) {
    *out = heapArr[1];
    heapArr[1] = heapArr[hn--];
    int i = 1;
    for (;;) {
        int l = i << 1, r = l | 1, m = i;
        if (l <= hn && heapArr[l].key < heapArr[m].key) m = l;
        if (r <= hn && heapArr[r].key < heapArr[m].key) m = r;
        if (m == i) break;
        HN tmp = heapArr[m]; heapArr[m] = heapArr[i]; heapArr[i] = tmp;
        i = m;
    }
}

static int cmp_desc(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x < y) - (x > y);
}

/*
 * Se um carro com tempo t entra em uma fila com c carros atras dele
 * (ele vai para a frente da fila, pois processamos carros em ordem
 * DECRESCENTE de t), cada carro atras dele espera t*F_j: custo imediato
 * = c * F_j. Apos inserir a oferta da maquina vira (c+1)*F_j.
 * Escolher sempre a menor oferta disponivel produz (provavel por troca),
 * elemento a elemento, o menor multiplicado valido; emparelhado com
 * tempos em ordem decrescente (rearranjo), da o otimo global.
 */
int main(void) {
    int n = (int)readInt();
    int m = (int)readInt();
    for (int i = 0; i < n; i++) tval[i] = (int)readInt();
    for (int j = 0; j < m; j++) fval[j] = readInt();

    qsort(tval, (size_t)n, sizeof(int), cmp_desc);

    for (int j = 0; j < m; j++) hpush(0, j);

    long long ans = 0;
    for (int i = 0; i < n; i++) {
        HN top;
        hpop(&top);
        ans += (long long)tval[i] * top.key;
        hpush(top.key + fval[top.idx], top.idx);
    }

    printf("%lld\n", ans);
    return 0;
}
